inspection=json.loads((w/'inspection.json').read_text());names=inspection['accepted']
assert all(n in notes for n in names)
imgs={}
for n in names:
 f=w/'screenshots'/('v151-rollback-'+n+'.png');assert f.is_file();shutil.copy2(f,r/f.name);imgs[f.name]=hashlib.sha256(f.read_bytes()).hexdigest()
log=(w/'minecraft-main-151.log').read_text(errors='replace');start=log.rfind('[STRATUS_QA] PACK Stratus-1.5.1-Refraction131.zip');assert start>=0
shader_errors=[line for line in log[start:].splitlines() if re.search(r'ShaderCompileException|Failed to create shader rendering pipeline|Shader compilation failed|NoMoreTextureUnits|GL_INVALID|undeclared identifier|Index 1 out of bounds',line,re.I)];assert not shader_errors,shader_errors
checks={k:a for k,a in v.items()};checks.update(status='shader load and finite visual coverage checked; clean FPS pending',runtime={'game':'Minecraft 1.21.11','iris':'1.10.8','sodium':'0.8.14','gpu':'Apple M1 / OpenGL 4.1','instance':'Main: Minecraft (1)','world':'Stratus Terrain Lab','world_generator':'minecraft:noise / normal overworld','creative':True,'tested_archive':'Stratus-1.5.1-Refraction131.zip','shader_specific_errors_after_selected_rollback':0,'accepted_capture_count':len(names)},water={'refraction':'v1.3.1 normal-offset formula and original single shoreline depth guard','physical_snell_geometry_transmission':False,'extra_geometry_views':0,'shadow_passes':0,'default_reflection_step_limit':48,'high_reflection_step_limit':192},performance={'clean_foreground_fps_verified':False,'reason':'User requested waiting for their cleanup command; earlier background/loaded-system measurements are not release FPS.','default_water_scale':0.5,'default_atmosphere_scale':0.5,'sky_reflection_cache':[256,128],'default_cloud_steps':64,'default_fog_steps':36},limits=['Screen-space reflection cannot reconstruct off-screen or hidden terrain. Underwater total-reflection fallback can look plain blue.','The v1.3.1 refraction is a normal-offset screen approximation, not a geometric Snell ray tracer.','Cloud scattering, volumetric fog and block material absorption are approximations. Balanced atmosphere is reconstructed from a lower-resolution target.','Finite visual inspection does not cover every world, mod, texture pack or camera.'],inspection=inspection,capture_sha256=imgs,non_shader_findings=['An initial fixture function used an unavailable gamerule name and was discarded; its replacement uses fills below the normal block limit and built successfully.','Rejected captures include cameras displaced by collision, early fixture captures before construction, and the mountain-terrain frame obscured by cloud.','Main logs include unrelated offline account/Realms/voice-chat/resource-pack warnings and errors.'])
(p/'CHECKS.json').write_text(json.dumps(checks,indent=2)+'\n');(r/'results.json').write_text(json.dumps(checks,indent=2)+'\n')
validation=f'''STRATUS 1.5.1 — VALIDATION\n19 October 2026\n\n768 native macOS OpenGL compile/link checks passed: 96 program pairs across\neight variants. Offline compatibility shims are distinct from Iris runtime.\n44 actual GLSL GPU cases passed, zero OpenGL errors. Cases include the original\nv1.3.1 refraction offset, zero offset and foreground depth guard; screen-space\nreflection hit/miss/medium checks; dielectric Fresnel and total reflection;\nBeer extinction; material absorption and wet films; vanilla face brightness;\ncloud direction/depth/world anchoring and spatial fog.\n53 settings are reachable through the menus and have English labels.\nAll 228 shader/config/data files match the archive loaded in Main.\n\nActual Minecraft 1.21.11 / Iris 1.10.8 / Sodium 0.8.14 / Apple M1 OpenGL 4.1\nloaded the rollback in Main's NEW normal world, Stratus Terrain Lab.\n{len(names)} accepted in-game captures were visually inspected. The test subjects\ninclude a generated forest river, above/below-water views, a controlled\nsubmerged wooden structure, materials, volumetric clouds and available terrain\nviews listed in CHECKS.json. Other Main worlds and installed mod files are\noutside the automated test actions.\n\nWater refraction now uses v1.3.1's inexpensive normal-offset formula and original\nshoreline depth guard. The eight-view geometry cache and all shadow/capture\nprograms are removed. Later biome water/extinction, cave-light response and\nFresnel reflection remain. No claim of physically traced Snell transmission.\nScreen reflections cannot recover hidden/off-screen surfaces, and underwater\nfallback may appear plain blue. The default refraction edge-protection mode\nis the original single v1.3.1 guard; higher modes add conservative checks.\n\nPerformance work includes independent half-resolution water and atmosphere\nwith depth/normal reconstruction, a smaller sky-reflection cache, bounded\nreflection searches and fewer repeated cloud/fog samples. Full-resolution\nmodes remain selectable. Clean foreground FPS validation is PENDING the user's\ncleanup command. Earlier loaded-system/background measurements do not establish\nnormal-play performance, and this build makes no 60-fps claim.\n\nThe full log contains unrelated account, voice-chat and resource-pack errors,\na rejected early fixture command and rejected displaced-camera checks. None\nis represented as a successful visual test. See results.json for finite scope\nand known limitations.\n'''
(p/'VALIDATION.txt').write_text(validation);(p/'IN-GAME-TEST.txt').write_text(validation)
e=html.escape
cards=''.join(f'<figure><a href="v151-rollback-{e(n)}.png"><img loading="lazy" src="v151-rollback-{e(n)}.png" alt="{e(n)}"></a><figcaption><b>{e(n.replace("-"," "))}</b><p>{e(notes[n])}</p></figcaption></figure>' for n in names)
(r/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Stratus 1.5.1 — v1.3.1 refraction rollback</title><style>body{background:#101820;color:#e6eff4;font:16px/1.6 system-ui;max-width:1280px;margin:auto;padding:28px}a{color:#9bd9ec}h1{font-size:36px}p{color:#c2d2dc}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}figure{margin:0;background:#1a2b36;border-radius:8px;overflow:hidden}img{width:100%;display:block}figcaption{padding:12px 16px}figcaption p{font-size:14px;margin:6px 0}.note{padding:16px;background:#273743;border-left:3px solid #dcb773}@media(max-width:720px){.grid{grid-template-columns:1fr}}</style><h1>Stratus 1.5.1</h1><p>Water refraction restored to v1.3.1. The experimental eight-view geometry rendering is removed. Newer clouds, fog, materials, vanilla face shading and exposure controls remain.</p><p>768 compile/link checks · 44 GPU cases · 53 reachable controls · actual Main instance / new normal world</p><p class="note">Clean foreground FPS testing is pending the user's cleanup command. No 60-fps claim. Off-screen underwater reflections remain limited and can use a plain-blue fallback. This is screen-space refraction, not geometric Snell ray tracing.</p><h2>Inspected actual Minecraft captures</h2><p>Unmodified frames. Specific block tests use a clearing inside the new normal world; terrain tests use generated terrain. Rejected collision, missing-fixture and cloud-obscured terrain frames are excluded.</p><div class="grid">'''+cards+'''</div><h2>Review in Main</h2><p>World: <b>Stratus Terrain Lab</b>. Natural river: <code>/tp @s 164.5 64.5 32.5 0 18</code>. Controlled fixtures: <code>/tp @s 4096 100 4085</code>.</p><p><a href="results.json">Validation details, limitations and hashes</a> · <a href="../Stratus-1.5.1.zip">Installable shader ZIP</a></p></html>''')
